/* Source: shared/lib/orders.js; openPaymentItemSheet. Generated by standalone-build.mjs. */
function openPaymentItemSheet(row,trigger){
    if(!paymentItemSheet || !row) return;
    const isAddon=Boolean(row.dataset.orderAddon);
    const key=isAddon ? row.dataset.orderAddon : row.dataset.orderItem;
    const control=row.querySelector('[data-qty]');
    if(!key || (!isAddon && !control)) return;
    const quantity=Math.max(0,Number(isAddon
      ? flowState.orderState.addonQuantities[key]
      : flowState.orderState.quantities[key]) || 0);
    paymentItemDraft={
      key,
      type:isAddon ? 'addon' : 'medicine',
      quantity,
      originalQuantity:quantity,
      max:isAddon ? 10 : Number(control.dataset.max || quantity),
      unit:isAddon ? Number(ADDON_PRICES[key] || 0) : Number(control.dataset.unit || 0),
      allowIncrease:true
    };
    paymentItemReturnFocus=trigger || null;
    const sourceImage=row.querySelector('.checkout-order__thumb img');
    const image=paymentItemSheet.querySelector('[data-payment-item-image]');
    if(image && sourceImage) image.src=sourceImage.currentSrc || sourceImage.src;
    const name=paymentItemSheet.querySelector('[data-payment-item-name]');
    const description=paymentItemSheet.querySelector('[data-payment-item-description]');
    if(name) name.textContent=row.querySelector('.checkout-order__name')?.textContent.trim() || 'รายการยา';
    if(description) description.textContent=row.querySelector('.checkout-order__note')?.textContent.trim() || '';
    syncPaymentItemDraft();
    paymentItemSheet.hidden=false;
    paymentItemSheet.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
    paymentItemSheet.querySelector('.payment-item-dialog')?.focus({preventScroll:true});
  }

/* Source: shared/lib/orders.js; closePaymentItemSheet. Generated by standalone-build.mjs. */
function closePaymentItemSheet(){
    if(!paymentItemSheet || paymentItemSheet.hidden) return;
    paymentItemSheet.hidden=true;
    paymentItemSheet.setAttribute('aria-hidden','true');
    document.body.classList.remove('modal-open');
    paymentItemDraft=null;
    const focusTarget=paymentItemReturnFocus;
    paymentItemReturnFocus=null;
    focusTarget?.focus({preventScroll:true});
  }

/* Source: shared/lib/intake.js; syncPaymentItemDraft. Generated by standalone-build.mjs. */
function syncPaymentItemDraft(){
    if(!paymentItemSheet || !paymentItemDraft) return;
    const quantity=paymentItemSheet.querySelector('[data-payment-item-quantity]');
    const price=paymentItemSheet.querySelector('[data-payment-item-price]');
    const minus=paymentItemSheet.querySelector('[data-payment-item-minus]');
    const plus=paymentItemSheet.querySelector('[data-payment-item-plus]');
    const limit=paymentItemSheet.querySelector('[data-payment-item-limit]');
    if(quantity) quantity.textContent=String(paymentItemDraft.quantity);
    if(price) price.textContent=baht(paymentItemDraft.unit*paymentItemDraft.quantity);
    if(minus) minus.disabled=paymentItemDraft.quantity<=0;
    if(plus) plus.disabled=!paymentItemDraft.allowIncrease || paymentItemDraft.quantity>=paymentItemDraft.max;
    if(limit){
      limit.textContent=paymentItemDraft.type==='addon'
        ? `ลดได้ถึง 0 และเพิ่มได้สูงสุด ${paymentItemDraft.max} ชิ้น`
        : 'ลดหรือเพิ่มกลับได้ ไม่เกินจำนวนที่แพทย์สั่ง';
    }
  }

/* Source: shared/lib/orders.js; commitPaymentItemQuantity. Generated by standalone-build.mjs. */
function commitPaymentItemQuantity(quantity){
    if(!paymentItemDraft) return;
    const key=paymentItemDraft.key;
    const isAddon=paymentItemDraft.type==='addon';
    const nextQuantity=Math.max(0,Math.min(paymentItemDraft.max,quantity));
    if(isAddon){
      flowState.orderState.addOns[key]=nextQuantity>0;
      flowState.orderState.addonQuantities[key]=nextQuantity;
    }else{
      flowState.orderState.quantities[key]=nextQuantity;
    }
    invalidateFulfillmentQuote();
    persistFlowState();
    syncOrderCheckout();
    syncDeclinedMedicines();
    refreshMedicationCheckout();
    closePaymentItemSheet();
    const zeroMessage=isAddon ? 'ปรับสินค้าเป็น 0 ชิ้นแล้ว' : 'นำยาออกจากรายการแล้ว';
    showActionToast(nextQuantity<=0 ? zeroMessage : 'อัปเดตจำนวนแล้ว','success');
  }

/* Source: shared/lib/orders.js; applyPromoCode. Generated by standalone-build.mjs. */
function applyPromoCode(rawCode){
    const status = promoModal && promoModal.querySelector('[data-promo-status]');
    const code = (rawCode || '').trim().toUpperCase();
    if(!code){ if(status) status.textContent = '\u0e01\u0e23\u0e2d\u0e01\u0e42\u0e04\u0e49\u0e14\u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e25\u0e37\u0e2d\u0e01\u0e08\u0e32\u0e01\u0e23\u0e32\u0e22\u0e01\u0e32\u0e23\u0e14\u0e49\u0e32\u0e19\u0e1a\u0e19'; return; }
    const found = validPromoCodes[code];
    if(!found){ if(status) status.textContent = '\u0e42\u0e04\u0e49\u0e14\u0e19\u0e35\u0e49\u0e44\u0e21\u0e48\u0e2a\u0e32\u0e21\u0e32\u0e23\u0e16\u0e43\u0e0a\u0e49\u0e44\u0e14\u0e49 \u0e2b\u0e23\u0e37\u0e2d\u0e2b\u0e21\u0e14\u0e2d\u0e32\u0e22\u0e38\u0e41\u0e25\u0e49\u0e27'; return; }
    appliedPromo = { code, amount: found.amount };
    renderPromo();
    closePromoModal();
    showActionToast('\u0e43\u0e0a\u0e49\u0e42\u0e04\u0e49\u0e14 ' + code + ' \u0e41\u0e25\u0e49\u0e27', 'success');
  }

/* Source: shared/lib/orders.js; openPromoModal. Generated by standalone-build.mjs. */
function openPromoModal(){
    if(!promoModal) return;
    pendingPromoCode = appliedPromo && appliedPromo.code;
    promoModal.querySelectorAll('[data-promo-option]').forEach(opt => {
      opt.setAttribute('aria-selected', String(opt.dataset.promoOption === pendingPromoCode));
    });
    const input = promoModal.querySelector('#promoInput');
    if(input) input.value = appliedPromo ? appliedPromo.code : '';
    const status = promoModal.querySelector('[data-promo-status]');
    if(status) status.textContent = '';
    promoModal.hidden = false;
    promoModal.setAttribute('aria-hidden','false');
    document.body.classList.add('modal-open');
    if(input) input.focus();
  }

/* Source: pages/address/page.js; syncDeliveryAddress. Generated by standalone-build.mjs. */
function syncDeliveryAddress({hydrateForm=false}={}){
    const address=flowState.orderState.address;
    const confirmed=Boolean(flowState.orderState.addressConfirmed && address.building && address.line && address.district);
    const pickup=flowState.orderState.fulfillmentMode==='pickup';
    /* Client, 23 Sep: no description lines on the checkout rows. "ยังไม่ได้
       เลือกที่อยู่จัดส่ง" under "ที่อยู่จัดส่ง" said nothing the label and the
       "เพิ่มที่อยู่" tag beside it did not already say, so the second line is
       shown only once it carries the address itself. */
    document.querySelectorAll('[data-payment-address]').forEach(el => {
      el.textContent=confirmed ? deliveryAddressSummary(address) : '';
      el.hidden=!confirmed;
    });
    /* Client, 1 Sep: New wants the name on this screen, the way a delivery app
       shows it — who it is going to sits with where it is going, so the patient
       can check both without opening the address screen. Data-driven, so there
       is no fixed string here for the language pass to miss. */
    const recipient=document.querySelector('[data-payment-recipient]');
    if(recipient){
      const name=recipientNameParts(address);
      const fullName=[name.firstName,name.lastName].filter(Boolean).join(' ');
      const parts=[fullName,address.recipientPhone].map(part => (part || '').trim()).filter(Boolean);
      recipient.textContent=parts.join(' · ');
      recipient.hidden=!(confirmed && parts.length);
    }
    const row=document.querySelector('[data-payment-address-row]');
    const title=document.querySelector('[data-fulfillment-address-title]');
    if(title) title.hidden=confirmed;
    if(row){
      row.dataset.go='address';
      row.classList.toggle('checkout-row--empty',!confirmed);
      row.setAttribute('aria-label',confirmed
        ? `${pickup ? 'เปลี่ยนตำแหน่ง' : 'เปลี่ยนที่อยู่จัดส่ง'}: ${deliveryAddressSummary(address)}`
        : (pickup ? 'เพิ่มตำแหน่งเพื่อค้นหาสาขาใกล้คุณ' : 'เพิ่มที่อยู่จัดส่ง'));
    }
    const compactRow=document.querySelector('[data-delivery-address-detail-section]');
    if(compactRow) compactRow.dataset.go='address';
    const action=document.querySelector('[data-payment-address-action]');
    if(action){
      action.textContent=pickup ? 'เพิ่มตำแหน่ง' : 'เพิ่มที่อยู่';
      /* Once the address is on the row the tag repeated what the row and its
         chevron already said, so it is only shown while one is missing
         (client, 29 Sep). */
      action.hidden=confirmed;
      // Missing address blocks payment, so the tag carries the error tone.
      action.classList.toggle('checkout-row__tag--error',!confirmed);
    }
    const detail=document.querySelector('[data-payment-address-detail]');
    if(detail){
      const dropoffLabels={lobby:'วางไว้ที่ล็อบบี้',doorstep:'วางไว้หน้าประตู',security:'ฝากไว้ที่ รปภ.',hand:'ส่งให้ฉันโดยตรง'};
      const floor=address.floor ? (/^ชั้น\s/.test(address.floor) ? address.floor : `ชั้น ${address.floor}`) : '';
      detail.textContent=confirmed
        ? [floor,dropoffLabels[address.dropoffMethod || 'hand']].filter(Boolean).join(' · ')
        : '';
      detail.hidden=!confirmed;
    }
    const formAddress=deliveryAddressDraft();
    const previewTitles=document.querySelectorAll('[data-address-preview-title]');
    const previewDetails=document.querySelectorAll('[data-address-preview-detail]');
    const hasDraft=Boolean(formAddress.building && formAddress.line && formAddress.district);
    previewTitles.forEach(el => { el.textContent=hasDraft ? (formAddress.building || 'ที่อยู่จัดส่ง') : 'เลือกที่อยู่จัดส่ง'; });
    const previewParts=[...new Set([formAddress.building,formAddress.line,formAddress.district].filter(Boolean))];
    previewDetails.forEach(el => { el.textContent=hasDraft
      ? previewParts.join(' · ')
      : 'เลือกตำแหน่งจากแผนที่เพื่อระบุที่อยู่จัดส่ง'; });
    renderAddressPinPreview();
    syncAddressEditorReadiness();
    syncCheckoutReadiness();
    if(!hydrateForm) return;
    const screen=document.getElementById('address');
    if(!screen) return;
    /* The recipient defaults to the account holder on the ordinary address
       page, so a first order opens prefilled with the name and phone captured
       at signup. Adding a *new* address is the exception: that page is blank
       by request (client, 5 Oct), because the second address a patient saves
       is often going to somebody else. */
    const creatingNewAddress=flowState.addressDraftMode==='new';
    const recipientParts=creatingNewAddress
      ? {firstName:String(formAddress.recipientFirstName || '').trim(),
         lastName:String(formAddress.recipientLastName || '').trim()}
      : recipientNameParts(formAddress);
    const values={
      recipientFirstName:recipientParts.firstName,
      recipientLastName:recipientParts.lastName,
      recipientPhone:creatingNewAddress
        ? (formAddress.recipientPhone ?? '')
        : (formAddress.recipientPhone ?? flowState.verifiedPhone ?? ''),
      addrSearch:formAddress.building,
      addrLabel:formAddress.label,
      addrBuilding:formAddress.building,
      addrFloor:formAddress.floor,
      addrLine:formAddress.line,
      addrSubdistrict:formAddress.subdistrict,
      addrDistrictName:formAddress.districtName,
      addrProvince:formAddress.province,
      addrPostcode:formAddress.postcode,
      addrDistrict:formAddress.district,
      addrNote:formAddress.note
    };
    Object.entries(values).forEach(([id,value]) => {
      const input=screen.querySelector(`#${id}`);
      if(input) input.value=id==='recipientPhone' ? formatPhoneForDisplay(value) : (value || '');
    });
    const dropoff=screen.querySelector(`input[name="dropoffMethod"][value="${formAddress.dropoffMethod || 'hand'}"]`);
    if(dropoff) dropoff.checked=true;
    screen.dataset.selectedKm=formAddress.km || '3.2';
    /* Hydration writes .value directly, so no input event fires and the ×
       buttons keep whatever state they had. Re-sync them here or an emptied
       field keeps offering a clear (client, 19 Aug). */
    syncFieldClearButtons();
    writeDeliveryAddressDraft(screen,formAddress);
    syncAddressEditorReadiness();
  }

/* Source: pages/ineligible/page.js; openRedFlagSheet. Generated by standalone-build.mjs. */
function openRedFlagSheet(screen,index){
    const state=intakeQuestionPageState(screen);
    const source=state.questions[index];
    if(!redFlagSource(source)) return;
    document.getElementById('red-flag-modal')?.remove();
    const flaggedOptions=[...source.querySelectorAll('[data-flag]')];
    const entries=flaggedOptions.length ? flaggedOptions.map(option=>({title:option.textContent.trim(),yes:option,no:null})) : [{title:source.querySelector('.section-label').textContent.trim(),yes:source.querySelectorAll('.option')[0],no:source.querySelectorAll('.option')[1]}];
    const answers=entries.map(entry=>entry.yes.getAttribute('aria-selected')==='true'?'yes':entry.no?.getAttribute('aria-selected')==='true'?'no':null);
    let step=0;
    const modal=document.createElement('div');modal.id='red-flag-modal';modal.className='modal-layer';
    modal.innerHTML='<button class="modal-layer__scrim" type="button" aria-label="ย้อนกลับ"></button><section class="modal-dialog health-history-dialog" role="dialog" aria-modal="true" aria-labelledby="red-flag-title"><h2 id="red-flag-title">ยืนยันข้อมูลความปลอดภัย</h2><p class="hint" data-step></p><div data-questions></div><div class="modal-dialog__actions"><button class="btn btn--primary" type="button" data-next>ถัดไป</button><button class="btn btn--ghost" type="button" data-prev>ย้อนกลับ</button></div></section>';
    document.body.append(modal);document.body.classList.add('modal-open');
    const close=()=>{modal.remove();document.body.classList.remove('modal-open');};
    const back=()=>{if(step){step--;render();}else{close();if(index>0)activateIntakeQuestionPage(screen,index-1);else screen.querySelector('[data-back]')?.click();}};
    function render(){
      modal.querySelector('[data-step]').textContent=entries.length>3?`${step+1} / ${Math.ceil(entries.length/3)}`:'';
      const host=modal.querySelector('[data-questions]');host.replaceChildren();
      entries.slice(step*3,step*3+3).forEach((entry,offset)=>{
        const i=step*3+offset,field=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent=entry.title;field.append(legend);
        const options=document.createElement('div');options.className='partner-binary';options.setAttribute('role','radiogroup');options.setAttribute('aria-label',entry.title);
        ['no','yes'].forEach(value=>{const button=document.createElement('button');button.type='button';button.className='partner-binary__option';button.setAttribute('role','radio');button.setAttribute('aria-checked',String(answers[i]===value));button.textContent=value==='yes'?'ใช่':'ไม่';button.onclick=()=>{answers[i]=value;if(entry.no)source.querySelectorAll('.option').forEach(option=>option.setAttribute('aria-selected','false'));entry.yes.setAttribute('aria-selected',String(value==='yes'));entry.no?.setAttribute('aria-selected',String(value==='no'));saveIntakeDraft();render();};options.append(button);});field.append(options);host.append(field);
      });
      modal.querySelector('[data-next]').disabled=answers.slice(step*3,step*3+3).some(value=>value===null);
    }
    modal.querySelector('[data-prev]').onclick=back;modal.querySelector('.modal-layer__scrim').onclick=back;
    modal.onkeydown=event=>{if(event.key==='Escape'){event.stopPropagation();back();}};
    modal.querySelector('[data-next]').onclick=()=>{
      if(answers.includes('yes')){close();flowState.ineligibleReturn=screen.id;persistFlowState();show('ineligible');return;}
      if((step+1)*3<entries.length){step++;render();return;}
      if(flaggedOptions.length){source.querySelectorAll(".option:not([data-flag])").forEach(option=>option.setAttribute("aria-selected","true"));}
      saveIntakeDraft();close();syncIntakeDropdownContinue(screen);
      if(!advanceIntakeQuestionPage(screen))screen.querySelector('.screen__footer .btn--primary[data-go]')?.click();
    };
    render();modal.querySelector('[role="radio"]')?.focus();
  }

/* Source: pages/address/page.js; renderAddressPinPreview. Generated by standalone-build.mjs. */
function renderAddressPinPreview(){
    document.querySelectorAll('[data-address-pin-map]').forEach(host => {
      const plane=host.querySelector('[data-address-pin-tiles]');
      if(!plane) return;
      if(osmView.failed){ plane.innerHTML=''; return; }
      const width=host.clientWidth, height=host.clientHeight;
      if(!width || !height)return;
      const z=osmView.zoom, scale=Math.pow(2,z);
      const originX=osmLonToX(osmView.lon,z)*OSM_TILE_SIZE - width/2;
      const originY=osmLatToY(osmView.lat,z)*OSM_TILE_SIZE - height/2;
      const firstX=Math.floor(originX/OSM_TILE_SIZE), lastX=Math.floor((originX+width)/OSM_TILE_SIZE);
      const firstY=Math.floor(originY/OSM_TILE_SIZE), lastY=Math.floor((originY+height)/OSM_TILE_SIZE);
      const tiles=[];
      for(let y=firstY;y<=lastY;y++){
        if(y<0 || y>=scale) continue;
        for(let x=firstX;x<=lastX;x++){
          const wrapped=((x%scale)+scale)%scale;
          tiles.push(`<img class="osm-map__tile" alt="" aria-hidden="true" loading="eager" src="${OSM_TILES}/${z}/${wrapped}/${y}.png"
            style="left:${Math.round(x*OSM_TILE_SIZE-originX)}px;top:${Math.round(y*OSM_TILE_SIZE-originY)}px">`);
        }
      }
      plane.innerHTML=tiles.join('');
      plane.querySelectorAll('img').forEach(img => {
        img.addEventListener('error',() => { plane.innerHTML=''; },{once:true});
      });
    });
  }

/* Source: pages/address/page.js; syncAddressEditorReadiness. Generated by standalone-build.mjs. */
function syncAddressEditorReadiness(){
    const screen=document.getElementById('address');
    if(!screen)return;
    const a=readAddressInputs();
    const locationComplete=Boolean(a.building && a.line && a.subdistrict && a.districtName && a.province && /^\d{5}$/.test(a.postcode));
    const recipientComplete=Boolean(a.recipientFirstName && a.recipientLastName && /^0\d{9}$/.test(normalizePhone(a.recipientPhone)));
    const button=screen.querySelector('[data-address-save]');
    if(button){
      button.disabled=false;
      button.classList.remove('btn--blocked');
      button.removeAttribute('aria-disabled');
      /* The form saves to the book and sends the order to this address, in
         both modes — the list is where an address is merely chosen. */
      button.textContent='บันทึกและใช้ที่อยู่นี้';

    }
    const recipient=screen.querySelector('[data-address-editor-recipient]');
    const phone=screen.querySelector('[data-address-editor-phone]');
    if(recipient) recipient.textContent=[a.recipientFirstName,a.recipientLastName].filter(Boolean).join(' ') || 'เพิ่มข้อมูลผู้รับยา';
    if(phone) phone.textContent=formatPhoneForDisplay(a.recipientPhone || '') || 'ยังไม่มีเบอร์โทรศัพท์';
  }

/* Source: pages/address/page.js; readAddressInputs. Generated by standalone-build.mjs. */
function readAddressInputs(){
    const v = id => (document.getElementById(id)?.value || '').trim();
    syncComposedDistrict();
    return {
      recipientFirstName:v('recipientFirstName'), recipientLastName:v('recipientLastName'),
      recipientName:[v('recipientFirstName'),v('recipientLastName')].filter(Boolean).join(' '), recipientPhone:normalizePhone(v('recipientPhone')),
      label:v('addrLabel'),
      remember:true,
      building:v('addrBuilding'), floor:v('addrFloor'), line:v('addrLine'),
      subdistrict:v('addrSubdistrict'), districtName:v('addrDistrictName'),
      province:v('addrProvince'), postcode:v('addrPostcode'),
      district:v('addrDistrict'), note:v('addrNote'),
      dropoffMethod:document.querySelector('#address input[name="dropoffMethod"]:checked')?.value || 'hand'
    };
  }

/* Source: pages/address/page.js; syncComposedDistrict. Generated by standalone-build.mjs. */
function syncComposedDistrict(){
    const v=id=>(document.getElementById(id)?.value||'').trim();
    const el=document.getElementById('addrDistrict');
    if(!el) return;
    el.value=composeDistrict({subdistrict:v('addrSubdistrict'),districtName:v('addrDistrictName'),
                              province:v('addrProvince'),postcode:v('addrPostcode')});
    el.dispatchEvent(new Event('change',{bubbles:true}));
  }
